	@Override
	public void setupAnim(State state) {
		super.setupAnim(state);
		head.yRot += state.yRot * 0.017453292F * 0.8F;
		head.xRot += state.xRot * 0.017453292F * 0.8F;
		ear_r.zRot += Mth.sin(state.ageInTicks * 0.11F + 2.0F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		ear_l.zRot += Mth.sin(state.ageInTicks * 0.11F + 0.0F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		leg_fr.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.8F * state.walkAnimationSpeed;
		shin_fr.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 4.141592653589793F) * -0.32000000000000006F * state.walkAnimationSpeed;
		leg_fl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.8F * state.walkAnimationSpeed;
		shin_fl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.0F) * -0.32000000000000006F * state.walkAnimationSpeed;
		leg_br.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.8F * state.walkAnimationSpeed;
		shin_br.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.0F) * -0.32000000000000006F * state.walkAnimationSpeed;
		leg_bl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.8F * state.walkAnimationSpeed;
		shin_bl.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 4.141592653589793F) * -0.32000000000000006F * state.walkAnimationSpeed;
		tail0.zRot += Mth.sin(state.ageInTicks * 0.13F + 0.0F) * (0.12F + 0.15F * state.walkAnimationSpeed);
		tail1.xRot += Mth.sin(state.ageInTicks * 0.14F + 0.8F) * (0.15F + 0.15F * state.walkAnimationSpeed);
		tail2.zRot += Mth.sin(state.ageInTicks * 0.15F + 1.6F) * (0.18F + 0.15F * state.walkAnimationSpeed);
		tail3.xRot += Mth.sin(state.ageInTicks * 0.16F + 2.4000000000000004F) * (0.21F + 0.15F * state.walkAnimationSpeed);
		wing_l.zRot += state.airborne ? Mth.sin(state.ageInTicks * 1.0F + 0.0F) * 0.8F + 0.85F : 0.0F;
		wing_l2.zRot += state.airborne ? Mth.sin(state.ageInTicks * 1.0F + 0.9F) * 0.44000000000000006F + -0.5F : 0.0F;
		wing_r.zRot += state.airborne ? Mth.sin(state.ageInTicks * 1.0F + 0.0F) * -0.8F + -0.85F : 0.0F;
		wing_r2.zRot += state.airborne ? Mth.sin(state.ageInTicks * 1.0F + 0.9F) * -0.44000000000000006F + 0.5F : 0.0F;
	}
